open_access": {"is_oa": true, "oa_status": "gold", "oa_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1155/2019/7895875", "any_repository_has_fulltext": true}, "primary_location": {"id": "doi:10.1155/2019/7895875", "doi": "https://doi.org/10.1155/2019/7895875", "is_oa": true, "landing_page_url": "https://doi.org/10.1155/2019/7895875", "pdf_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1155/2019/7895875", "source": {"id": "https://openalex.org/S207319443", "display_name": "Complexity", "issn_l": "1076-2787", "issn": ["1076-2787", "1099-0526"], "is_oa": true, "is_in_doaj": true, "is_core": true, "listed_in": ["anvur-scientific", "cwts-core", "doaj", "jufo-1", "poland-70", "russia-white-list-1", "vabb-shw"], "host_organization": "https://openalex.org/P4310319869", "host_organization_name": "Hindawi Publishing Corporation", "host_organization_lineage": ["https://openalex.org/P4310319869", "https://openalex.org/P4310320595"], "host_organization_lineage_names": ["Hindawi Publishing Corporation", "Wiley"], "type": "journal"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Complexity", "raw_type": "journal-article"}, "abstract": "The increasing development of autonomous intelligent systems, such as smart vehicles, smart homes, and social robots, poses new challenges to face. Among them, ensuring that such systems behave lawfully is one of the crucial topics to be addressed for improving their employment in real contexts of daily life. In this work, we present an approach for norm compliance in the context of open and goal‐directed intelligent systems working in dynamic normative environments where goals, services, and norms may change. Such an approach complements a goal‐directed system modifying its goals and the way to achieve them for taking norms into accounts, thus influencing the practical reasoning process that goal‐oriented systems implement for figuring out what to do. The conformity to norms is established at the goal level rather than at the action level. The effect of a norm that acts at the goal level spreads out at the lower level of actions, thus also improving system flexibility. Recovery mechanisms are provided to face exceptional situations that could be caused by normative changes. A case study in the field of the business organizations is presented for demonstrating the strengths of the proposed solution."}]", "excerpt_truncated": true, "source_sha256": "8cd85e68e19442a6c55720490123e470a907fe90e10813de6da5afe4c3a841aa", "verification_required": true, "topic_domain": "unassigned_problem", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1109/ojcoms.2023.3294445", "doi:10.1155/2019/7895875", "openalex:W4383899788"], "source_candidates": ["https://doi.org/10.1109/ojcoms.2023.3294445", "https://ieeexplore.ieee.org/ielx7/8782661/8901158/10178010.pdf", "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1155/2019/7895875", "https://doi.org/10.1155/2019/7895875"], "source_candidate_identities": {}}
